def button(label,url=WA,secondary=False):
    return f'<a class="btn {"btn-line" if secondary else ""}" href="{E(url)}">{label}<span aria-hidden="true">↗</span></a>'
def label(text): return f'<p class="eyebrow"><span aria-hidden="true">/</span> {text}</p>'
def link(label,url):return f'<a class="arrow-link" href="{url}">{label} <span aria-hidden="true">↗</span></a>'
def placeholder(text):return f'<span class="missing">[PREENCHER] {text}</span>'
