media=masthead('ACF / MEDIA','CONTEÚDO PARA<br>QUEM <em>VIVE CARROS.</em>','YouTube, Tunercast e Instagram. Conhecimento e conversas sobre preparação, potência e alta performance.')+f'<section class="section wrap">{media_cards()}<div class="shop-band"><img src="/assets/merch.jpg" alt="Moletom da linha ACF Performance" width="121" height="121" loading="lazy"><div>{label("LINHA ACF")}<h2>VISTA ESSA <em>PAIXÃO.</em></h2><p>Camisetas e moletons da ACF Performance.</p></div>{button("Visitar a loja","https://www.lolja.com.br/acfperformance")}</div><p class="note">Curadoria de projetos, episódios e posts para esta página: {placeholder("links e imagens aprovados")}</p></section>'
page('/media/','Media — YouTube, Tunercast e Instagram','Explore o canal ACF Performance, o podcast Tunercast, o Instagram e a loja oficial.',media)
portal=masthead('ACF / REVENDEDORES','PARCERIA QUE<br>GERA <em>PERFORMANCE.</em>','Acesso restrito aos revendedores da ACF Performance.')+f'<section class="section wrap portal-grid"><article class="access-panel"><span class="code">01 / ACESSO EXISTENTE</span><h2>PORTAL DO<br><em>REVENDEDOR.</em></h2><p>Continue para o sistema oficial e utilize suas credenciais de revendedor.</p>{button("Acessar o portal oficial",OFFICIAL+"/portal/")}<p class="small">O login é realizado no ambiente original da ACF.</p>{link("Recuperar senha",OFFICIAL+"/portal/recuperar-senha.asp")}</article><article class="access-panel secondary"><span class="code">02 / ATENDIMENTO</span><h2>PRECISA<br>DE <em>AJUDA?</em></h2><p>Fale com a equipe para informações sobre acesso e atendimento aos revendedores.</p>{button("Falar com a ACF",WA,True)}<p>Cliente final? {link("Acesse sua área",OFFICIAL+"/area-do-cliente/")}</p></article></section>'
page('/portal/','Portal do revendedor','Acesso ao portal oficial dos revendedores ACF Performance e suporte da equipe.',portal)
contact=masthead('ACF / CONTATO','SEU PROJETO<br><em>COMEÇA AQUI.</em>','Fale com a ACF Performance em São Paulo. Orçamentos, cursos e dúvidas sobre o seu carro.',button('Conversar no WhatsApp'))+f'''<section class="section wrap contact-grid"><div><h2>VAMOS ENTENDER<br>O SEU <em>PROJETO.</em></h2><form id="contact-form"><label for="name">Nome *</label><input id="name" name="nome" required autocomplete="name" maxlength="100"><div class="form-two"><div><label for="email">E-mail</label><input id="email" name="email" type="email" autocomplete="email" maxlength="150"></div><div><label for="phone">Telefone</label><input id="phone" name="telefone" type="tel" autocomplete="tel" maxlength="30"></div></div><label for="city">Cidade</label><input id="city" name="cidade" autocomplete="address-level2" maxlength="100"><label for="message">Mensagem *</label><textarea id="message" name="mensagem" rows="5" required maxlength="1500" placeholder="Conte qual é o seu carro ou curso de interesse."></textarea><p class="small muted">Ao continuar, você poderá revisar e enviar a mensagem no WhatsApp. Este formulário não envia e-mail nem salva seus dados.</p><button class="btn" type="submit">Preparar mensagem <span aria-hidden="true">↗</span></button><div id="contact-result" hidden><p role="status">Mensagem preparada. Revise e conclua o envio no WhatsApp.</p><a id="whatsapp-message" class="btn" target="_blank" rel="noopener">Abrir WhatsApp ↗</a></div></form></div><aside class="address-panel"><span class="eyebrow">VISITE A ACF</span><h3>SÃO PAULO.<br>VILA MARIANA.</h3><address>Av. Doutor Ricardo Jafet, 1050<br>Vila Mariana · São Paulo, SP<br>CEP 04260-000</address><a class="phone" href="tel:+5511984496047">(11) 98449-6047</a>{link('Abrir no Google Maps','https://www.google.com/maps/search/?api=1&query=Av.+Dr.+Ricardo+Jafet+1050+Sao+Paulo')}<p class="note">Horário de atendimento:<br>{placeholder('dias e horários')}</p></aside></section>'''
page('/contato/','Contato e orçamento','Fale com a ACF no WhatsApp (11) 98449-6047. Av. Doutor Ricardo Jafet, 1050, Vila Mariana, São Paulo.',contact)
